import{_ as e,a0 as l,w as m,s as r,ao as p,I as i,x as t,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Cinnamon 是一個被低估的神奇 Linux 桌面環境 | LCTT x X-CMD","titleTemplate":false,"description":"Cinnamon 是一個被低估的神奇 Linux 桌面環境 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cinnamon 是一個被低估的神奇 Linux 桌面環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cinnamon 是一個被低估的神奇 Linux 桌面環境 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221119.0 ⭐️⭐️ 7 Reasons Why Cinnamon is a Fantastic (Yet Underrated) Linux Desktop Environment","title":"Cinnamon 是一個被低估的神奇 Linux 桌面環境","tag":"202301","desc":""},"relativePath":"202301/20221119.0 ⭐️⭐️ 7 Reasons Why Cinnamon is a Fantastic (Yet Underrated) Linux Desktop Environment.md","filePath":"[post].md"}'),u={name:"202301/20221119.0 ⭐️⭐️ 7 Reasons Why Cinnamon is a Fantastic (Yet Underrated) Linux Desktop Environment.md"};function d(f,n,x,C,g,h){const s=l("Link");return m(),r("div",null,[n[25]||(n[25]=p('<h1 id="cinnamon-是一個被低估的神奇-linux-桌面環境" tabindex="-1">Cinnamon 是一個被低估的神奇 Linux 桌面環境 <a class="header-anchor" href="#cinnamon-是一個被低估的神奇-linux-桌面環境" aria-label="Permalink to “Cinnamon 是一個被低估的神奇 Linux 桌面環境”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/16/164642rr27xxt3zo72t7vl.jpg" alt=""></p><blockquote><p>Linux Mint 是我最喜歡的發行版之一，其旗艦版的默認 Cinnamon 桌面是我如此喜歡它的原因。</p></blockquote><p>Cinnamon 桌面提供的用户體驗可能並不炫目花哨。但是，用户有充分的理由喜歡這個桌面環境，並可以輕鬆地用它來完成工作。</p><p>在日復一日工作中，我們想要的是，一個能按預期工作且不造成妨礙的用户界面。</p><p>我認為 Cinnamon 桌面做對了幾件事，可以給你帶來了令人興奮的體驗。讓我在這裏介紹其中一些。</p><blockquote><p>如果你還不知道，Cinnamon 桌面是由 Linux Mint 的創建者 Clement Lefebvre 於 2011 年創建的 GNOME 3 復刻版，並經過多年的改進。</p></blockquote><h3 id="_1、熟悉的用户界面" tabindex="-1">1、熟悉的用户界面 <a class="header-anchor" href="#_1、熟悉的用户界面" aria-label="Permalink to “1、熟悉的用户界面”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/linux-mint-21-full.jpg" alt="Linux Mint 21"></p><p>構建 Cinnamon 的主要目的是為了保持 GNOME 2 的桌面風格。</p><p>而這就是為什麼與最流行的消費級桌面操作系統 Windows 相比，你會看到一個熟悉的桌面佈局。</p><p>當然，隨着時間的推移，Windows 11 已經進化了它的通常佈局。但是，訪問開始菜單、任務欄、托盤中的系統圖標和幾個窗口裝飾使其易於掌握。</p><p>無論你是 Windows 用户還是 macOS 用户，Cinnamon 的桌面佈局都不應該讓你感到有什麼挑戰。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/linux-mint-welcome.png" alt="Linux Mint 歡迎屏幕"></p><p>為了進一步幫助你，Linux Mint 的 “歡迎屏幕” 為你迅速提供了各種信息。</p><h3 id="_2、輕量級" tabindex="-1">2、輕量級 <a class="header-anchor" href="#_2、輕量級" aria-label="Permalink to “2、輕量級”">​</a></h3><p>為了獲得舒適的 Cinnamon 桌面體驗（通常使用 Linux Mint），有以下最低系統要求：</p><ul><li>4GB 內存</li><li>100 GB 的磁盤空間</li><li>1024×768 分辨率的屏幕</li></ul><p>在現代計算時代，這些規格應該適合幾乎所有人。所以，你不必擔心需要一個瘋狂的內存或磁盤空間來運行由 Cinnamon 驅動的 Linux 發行版。</p>',19)),i("p",null,[n[1]||(n[1]=t("當然，你可以嘗試 ",-1)),a(s,{href:"https://itsfoss.com/install-cinnamon-on-ubuntu/"},{default:o(()=>[...n[0]||(n[0]=[t("在 Ubuntu 上安裝 Cinnamon 桌面",-1)])]),_:1}),n[2]||(n[2]=t("。",-1))]),n[26]||(n[26]=p('<p>但是，在本文中，我們認為 Linux Mint 是理想的使用案例。</p><h3 id="_3、快速的性能而不犧牲用户體驗" tabindex="-1">3、快速的性能而不犧牲用户體驗 <a class="header-anchor" href="#_3、快速的性能而不犧牲用户體驗" aria-label="Permalink to “3、快速的性能而不犧牲用户體驗”">​</a></h3><p>當我們想到一個輕量級的桌面環境時，我們通常會想像一個注重性能的、平淡無奇的用户界面。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/linux-mint-perf.png" alt="Linux Mint 首選項"></p><p>在 Cinnamon 桌面上，情況並非如此。它確實包括了各種細微的動畫和特色的圖標/主題，即使不是最好的，其外觀也相當現代。</p><p>它以極簡的方式讓你看起來很賞心悦目。</p><p>通常情況下，我很喜歡漂亮的用户界面，但我仍然可以接受 Linux Mint 的簡單直接的用户體驗，並在雙顯示器設置（1440p + 1080p）上運行它。</p><p>它可能不是 Linux Mint Cinnamon 版最好的雙顯示器體驗（對我來説，第二個屏幕上沒有停靠區和麪板），但需要改進地方不多。</p><h3 id="_4、默認的自定義選項" tabindex="-1">4、默認的自定義選項 <a class="header-anchor" href="#_4、默認的自定義選項" aria-label="Permalink to “4、默認的自定義選項”">​</a></h3><p>你可能已經知道，在提供開箱即用的定製能力方面，KDE 可能是最棒的。</p><p>如果你對這種方式感到好奇，我們有超級有用的指南：</p>',11)),i("ul",null,[i("li",null,[a(s,{href:"https://itsfoss.com/kde-customization/"},{default:o(()=>[...n[3]||(n[3]=[t("KDE 定製指南",-1)])]),_:1})]),i("li",null,[a(s,{href:"https://itsfoss.com/properly-theme-kde-plasma/"},{default:o(()=>[...n[4]||(n[4]=[t("如何正確地給 KDE Plasma 定製主題（深度指南）",-1)])]),_:1})]),i("li",null,[a(s,{href:"https://itsfoss.com/best-kde-plasma-themes/"},{default:o(()=>[...n[5]||(n[5]=[t("最佳的 KDE Plasma 華麗主題",-1)])]),_:1})])]),n[27]||(n[27]=p('<p>但是，對於許多用户來説，這有些過於複雜了。</p><p>我認為 Linux Mint 給出了適量的額外控制/定製，你也可以在它的歡迎屏幕上了解到這些。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/cinnamon-theme-customize.png" alt="Cinnamon 主題定製"></p><p>一些你可以輕鬆定製的元素包括：</p><ul><li>桌面顏色（強調色）</li><li>淺色/深色主題切換</li><li>面板佈局</li><li>圖標、按鈕和鼠標指針</li></ul><p>你可以前往系統設置，並導航到 “主題”，找到必要的調整項。</p><p>推薦閲讀：</p>',7)),i("blockquote",null,[i("p",null,[i("strong",null,[a(s,{href:"https://itsfoss.com/customize-cinnamon-desktop/"},{default:o(()=>[...n[6]||(n[6]=[t("在 Linux 上定製 Cinnamon 桌面的 7 種方法",-1)])]),_:1})])])]),n[28]||(n[28]=i("h3",{id:"_5、為你的體驗增色的官方附加組件",tabindex:"-1"},[t("5、為你的體驗增色的官方附加組件 "),i("a",{class:"header-anchor",href:"#_5、為你的體驗增色的官方附加組件","aria-label":"Permalink to “5、為你的體驗增色的官方附加組件”"},"​")],-1)),n[29]||(n[29]=i("p",null,[i("img",{src:"https://itsfoss.com/content/images/wordpress/2022/11/cinnamon-desklet.png",alt:"Cinnamon 桌面部件"})],-1)),i("p",null,[n[8]||(n[8]=t("Linux Mint 支持各種插件來增強你的體驗。這些都是 ",-1)),a(s,{href:"https://cinnamon-spices.linuxmint.com"},{default:o(()=>[...n[7]||(n[7]=[t("Cinnamon 調味品",-1)])]),_:1}),n[9]||(n[9]=t(" 產品的一部分。它們包括：",-1))]),n[30]||(n[30]=p('<ul><li>主題</li><li>擴展程序</li><li><ruby>小程序<rt>Applet</rt></ruby></li><li><ruby>桌面組件<rt>Desklet</rt></ruby></li></ul><p>小程序和桌面組件是小型程序，你可以分別在面板（靠近系統托盤）和桌面上添加。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/applet-cinnamon.png" alt="小程序"></p><p>你可以管理系統默認的小程序，也可以從官方軟件庫下載更多的小程序。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/applets-cinnamon.png" alt="小程序"></p><p>同樣，你可以從可用的默認程序中添加桌面組件，或者從軟件庫中獲得新的。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/desklet-cinnamon.png" alt="桌面組件"></p><p>大量有價值的實用程序可以用來監控系統資源、檢查天氣，以及更多。</p><p>此外，你還可以訪問社區構建的各種主題，可以很容易地給你一個你一直想要的外觀。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/cinnamon-theme.png" alt="Cinnamon 主題"></p><p>通過補充上述所有的 “調味品”，你可以使用擴展來使面板透明，在桌面上添加水印，啓用窗口平鋪，並添加一些令人興奮的窗口動畫。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/linux-mint-extensions.png" alt="Linux Mint 擴展"></p><h3 id="_6、兼容和無縫的用户體驗" tabindex="-1">6、兼容和無縫的用户體驗 <a class="header-anchor" href="#_6、兼容和無縫的用户體驗" aria-label="Permalink to “6、兼容和無縫的用户體驗”">​</a></h3><p>為什麼我再次強調用户體驗？</p><p>Cinnamon 桌面最棒的地方在於它以尊重和支持所有功能的方式發展。</p><p>例如，如果你想安裝一個你在 KDE Plasma 上喜歡使用的應用程序，它在這裏也應該以同樣的方式工作。Cinnamon 桌面沒有什麼特別之處，會破壞這種體驗。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/gnome-accounts-cinnamon.png" alt="GNOME 賬户應用"></p><p>同樣地，該桌面增加了一些試圖與其他桌面環境的服務共存的功能。例如，支持使用 GNOME 在線賬户的日曆事件。</p><h3 id="_7、面板定製" tabindex="-1">7、面板定製 <a class="header-anchor" href="#_7、面板定製" aria-label="Permalink to “7、面板定製”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/linux-mint-panel.png" alt="Linux Mint 面板"></p><p>停靠區、任務欄或面板是用户界面的一個組成部分。</p><p>是的，其他的桌面環境也允許你在某種程度上同樣定製這些。但在 Cinnamon 中，你可以得到大量的控制權來調整它。</p><p>我認為你可以得到一個用户想要的所有基本選項。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>GNOME 和 KDE Plasma 是流行的桌面環境。然而，Cinnamon 在提供最佳用户體驗的基本部分上並不遜色。</p><p>你對 Cinnamon 桌面環境有什麼看法？你更喜歡用 Linux Mint 來嘗試它嗎？在下面的評論部分分享你的想法。</p><hr>',27)),i("p",null,[n[11]||(n[11]=t("via: ",-1)),a(s,{href:"https://itsfoss.com/why-cinnamon/"},{default:o(()=>[...n[10]||(n[10]=[t("https://itsfoss.com/why-cinnamon/",-1)])]),_:1})]),i("p",null,[n[16]||(n[16]=t("作者：",-1)),a(s,{href:"https://itsfoss.com/author/ankush/"},{default:o(()=>[...n[12]||(n[12]=[t("Ankush Das",-1)])]),_:1}),n[17]||(n[17]=t(" 選題：",-1)),a(s,{href:"https://github.com/lkxed"},{default:o(()=>[...n[13]||(n[13]=[t("lkxed",-1)])]),_:1}),n[18]||(n[18]=t(" 譯者：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...n[14]||(n[14]=[t("wxy",-1)])]),_:1}),n[19]||(n[19]=t(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...n[15]||(n[15]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[22]||(n[22]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[20]||(n[20]=[t("LCTT",-1)])]),_:1}),n[23]||(n[23]=t(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:o(()=>[...n[21]||(n[21]=[t("Linux中國",-1)])]),_:1}),n[24]||(n[24]=t(" 榮譽推出",-1))])])}const b=e(u,[["render",d]]);export{L as __pageData,b as default};
